'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './pulse-rings.css'

export type PulseRingsProps = {
    /** Shown in the centre, e.g. an avatar or icon. */
    children?: React.ReactNode
    /** Ring colour. */
    color?: string
    /** Number of rings in flight. */
    rings?: number
    /** Seconds per ring. */
    duration?: number
    /** Diameter of the rings' starting circle, in px. */
    size?: number
    paused?: boolean
    className?: string
}

const PulseRings = ({ children, color = 'rgba(52, 211, 153, 0.6)', rings = 3, duration = 2.8, size = 72, paused = false, className }: PulseRingsProps) => {
    const ref = React.useRef<HTMLSpanElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <span
        ref={ref}
        className={['rad-fx-pulse', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ width: size, height: size, '--rad-fx-pulse-color': color, '--rad-fx-pulse-duration': `${duration}s` } as React.CSSProperties}
    >
        {Array.from({ length: rings }, (_, i) => (
            <span key={i} className="rad-fx-pulse-ring" aria-hidden="true" style={{ animationDelay: `${(duration / rings) * i}s` }} />
        ))}
        <span className="rad-fx-pulse-center">{children}</span>
    </span>
}

export default PulseRings

.rad-fx-pulse {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.rad-fx-pulse-ring {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 2px solid var(--rad-fx-pulse-color);
    pointer-events: none;
    opacity: 0;
    animation: rad-fx-pulse var(--rad-fx-pulse-duration, 2.8s) cubic-bezier(0.2, 0.6, 0.3, 1) infinite;
}

.rad-fx-pulse[data-state='paused'] .rad-fx-pulse-ring { animation-play-state: paused; }

.rad-fx-pulse-center {
    position: relative;
    display: inline-flex;
}

@keyframes rad-fx-pulse {
    0% { transform: scale(1); opacity: 0.9; }
    100% { transform: scale(3.2); opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-pulse-ring { animation: none; opacity: 0.35; transform: scale(1.5); }
    .rad-fx-pulse-ring + .rad-fx-pulse-ring { display: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-pulse-ring { animation: none; opacity: 0.35; transform: scale(1.5); }
[data-rad-fx-motion='reduce'] .rad-fx-pulse-ring + .rad-fx-pulse-ring { display: none; }
